import { sys } from "cc";
import type { PlayerProfile } from "./PlayerProfile";

const SAVE_KEY = 'SAVE_DATA';
const CURRENT_VERSION = 1;

function createDefault(): PlayerProfile {
    return {
        version: CURRENT_VERSION,
        coins: 300,           // 起始金币，够建 3 个小摊
        buildings: [],
        ownedWeapons: [],
        lastBattleWin: false,
    };
}

export class ProfileStore {
    private _data: PlayerProfile = createDefault();
    private _loaded = false;

    load(): void {
        if (this._loaded) return;    // Battle / Hall 都调 init 时只读一次
        this._loaded = true;

        const raw = sys.localStorage.getItem(SAVE_KEY);
        if (raw) {
            try {
                const parsed = JSON.parse(raw) as Partial<PlayerProfile>;
                this._data = this._migrate(parsed);
                return;
            } catch (e) {
                console.warn('[ProfileStore] 存档解析失败，使用默认值', e);
            }
        }
        this._data = createDefault();
    }

    get data(): PlayerProfile {
        return this._data;
    }

    save(): void {
        try {
            sys.localStorage.setItem(SAVE_KEY, JSON.stringify(this._data));
        } catch (e) {
            console.warn('[ProfileStore] 存档写入失败', e);
        }
    }

    clear(): void {
        sys.localStorage.removeItem(SAVE_KEY);
        this._data = createDefault();
    }

    private _migrate(parsed: Partial<PlayerProfile>): PlayerProfile {
        // 未来加版本升级：if ((parsed.version ?? 0) < 2) { ... }
        return {
            version: CURRENT_VERSION,
            coins: parsed.coins ?? 300,
            buildings: parsed.buildings ?? [],
            ownedWeapons: parsed.ownedWeapons ?? [],
            lastBattleWin: parsed.lastBattleWin ?? false,
        };
    }
}